rm label{display:grid;gap:var(--space-1);font-weight:var(--text-weight-semibold)}.form input,.form textarea{border:1px solid var(--control-border);border-radius:var(--radius-control);padding:var(--space-2);background:var(--control-bg);color:var(--control-ink);font:inherit}.form textarea{min-height:5rem}.privacy{font-size:var(--text-size-meta);color:var(--text-muted)}@media(max-width:650px){.ride-card{align-items:start;flex-direction:column}}
.match-form{display:grid;grid-template-columns:repeat(4,1fr) auto auto;gap:var(--space-2);align-items:center;padding:var(--space-3);border:1px solid var(--border-subtle);border-radius:var(--radius-surface);background:var(--surface-base)}.match-form input{min-width:0;border:1px solid var(--control-border);border-radius:var(--radius-control);padding:var(--space-2);background:var(--control-bg);color:var(--control-ink);font:inherit}.commute-setup{border:1px solid var(--border-subtle);border-radius:var(--radius-surface);background:var(--surface-base)}.commute-setup summary{display:flex;min-height:4rem;align-items:center;padding:var(--space-3);cursor:pointer;list-style:none}.commute-setup summary::-webkit-details-marker{display:none}.commute-setup summary span{display:grid;gap:var(--space-1)}.commute-setup summary strong{color:var(--text)}.commute-setup summary small{color:var(--text-muted)}.commute-form{display:grid;gap:var(--space-3);padding:0 var(--space-3) var(--space-3)}.commute-form__privacy{margin:0;color:var(--text-muted);font-size:var(--text-size-body);line-height:1.45}.commute-form__fields{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:var(--space-2)}.commute-form :deep(input:not([type=checkbox])){width:100%;min-width:0;border:1px solid var(--control-border);border-radius:var(--radius-control);padding:var(--space-1) var(--space-2);background:var(--control-bg);color:var(--control-ink);font:inherit}.commute-form .check{display:flex;align-items:center;gap:var(--space-1);min-height:var(--control-height-default);font-size:var(--text-size-body);font-weight:var(--text-weight-semibold)}.commute-form .check input{width:auto}@media(max-width:850px){.match-form,.commute-form__fields{grid-template-columns:1fr 1fr}.match-form button,.commute-form button{justify-self:start}}@media(max-width:560px){.commute-form__fields{grid-template-columns:1fr}}
.rides-surface{gap:var(--space-3)}.rides-surface h1{font-size:var(--text-size-page-title);letter-spacing:var(--tracking-tight)}.rides-surface button{min-height:var(--control-height-default);border-radius:var(--radius-control);background:var(--control-bg);color:var(--control-ink)}.rides-surface button.active,.rides-surface button.primary{border-color:var(--accent);background:var(--accent);color:var(--canvas)}.rides-surface .app-button{border-radius:var(--radius-control);padding:var(--space-1) var(--space-3);background:var(--control-bg);color:var(--control-ink)}.rides-surface .app-button--primary{border-color:var(--accent);background:var(--accent);color:var(--canvas)}.rides-surface .app-button--danger{color:var(--danger)}.rides-trust-summary{display:grid;gap:var(--space-1);padding:var(--space-3);border:1px solid var(--border-subtle);border-radius:var(--radius-surface);background:var(--surface-raised);color:var(--text-muted)}.rides-trust-summary strong{color:var(--text)}.match-form{gap:var(--space-2);padding:var(--space-3);border:1px solid var(--border-subtle);border-radius:var(--radius-surface);background:var(--surface-base)}.ride-workspace{background:var(--surface-base)}.match-form input{border-color:var(--control-border);background:var(--control-bg);color:var(--control-ink)}.rides-surface button:hover{border-color:var(--border-strong);background:var(--surface-hover)}.rides-surface button.active:hover,.rides-surface button.primary:hover{border-color:var(--accent);background:var(--accent-hover,var(--accent));color:var(--canvas)}.commute-form :deep(input:not([type=checkbox])):focus-visible,.match-form input:focus-visible{border-color:var(--accent);outline:2px solid color-mix(in srgb,var(--accent) 35%,transparent);outline-offset:1px}.ride-visibility{display:grid;gap:var(--space-1);margin:0;border:1px solid var(--border-subtle);border-radius:var(--radius-control);padding:var(--space-2)}.ride-visibility legend{padding:0 var(--space-1);font-weight:var(--text-weight-semibold)}
.commute-weekdays{display:flex;flex-wrap:wrap;gap:var(--space-2);margin:0;border:1px solid var(--border-subtle);border-radius:var(--radius-control);padding:var(--space-2)}.commute-weekdays legend{width:100%;padding:0 var(--space-1);font-weight:var(--text-weight-semibold)}.commute-weekdays .check{min-height:var(--control-height-compact);padding:0 var(--space-1)}</style>
